// Read implements io.Reader, failing once the body exceeds its byte limit.
func (body *boundedIdentityBody) Read(p []byte) (int, error) {
	if body.remaining == 0 {
		var extra [1]byte
		n, _ := body.reader.Read(extra[:])
		if n > 0 {
			return 0, errors.New("identity response is too large")
		}
		return 0, io.EOF
	}
	if int64(len(p)) > body.remaining {
		p = p[:int(body.remaining)]
	}
	n, err := body.reader.Read(p)
	body.remaining -= int64(n)
	return n, err
}

// Close implements io.Closer by closing the underlying response body.
func (body *boundedIdentityBody) Close() error {
	return body.closer.Close()
}

