// identityControlFree reports whether a string contains no control characters.
func identityControlFree(value string) bool {
	for _, r := range value {
		if r < 0x20 || r == 0x7f {
			return false
		}
	}
	return true
}

// identityPointerValue resolves a configured JSON pointer and returns a valid
// ID string, allowing a null value only for an organization.
func identityPointerValue(data any, pointer, kind string) (any, error) {
	if pointer == "" || !strings.HasPrefix(pointer, "/") || len(pointer) > 512 {
		return nil, errors.New("the configured identity field is invalid")
	}
	value := data
	for _, raw := range strings.Split(strings.TrimPrefix(pointer, "/"), "/") {
		part := strings.ReplaceAll(strings.ReplaceAll(raw, "~1", "/"), "~0", "~")
		if object, ok := value.(map[string]any); ok {
			value, ok = object[part]
			if !ok {
				return nil, errors.New("the API identity response is missing a configured field")
			}
			continue
		}
		// RFC 6901 array indices: only the canonical decimal form of an
		// in-bounds index resolves ("01" and "+1" are never valid
		// indices).
		if array, ok := value.([]any); ok {
			index, indexErr := strconv.Atoi(part)
			if indexErr != nil || index < 0 || strconv.Itoa(index) != part || index >= len(array) {
				return nil, errors.New("the API identity response is missing a configured field")
			}
			value = array[index]
			continue
		}
		return nil, errors.New("the API identity response is missing a configured field")
	}
	if value == nil && kind == "organization" {
		return nil, nil
	}
	if text, ok := value.(string); ok && text != "" && len(text) <= 512 && identityControlFree(text) {
		return text, nil
	}
	if number, ok := value.(float64); ok && !math.IsNaN(number) && !math.IsInf(number, 0) && math.Trunc(number) == number && math.Abs(number) <= 9007199254740991 {
		return strconv.FormatInt(int64(number), 10), nil
	}
	return nil, errors.New("the API identity field must return a nonempty ID string or safe integer; only an organization may be null")
}

